// Copies the webR runtime (R compiled to WebAssembly) from node_modules into
// public/webr/ so the live-r block loads it SAME-ORIGIN (the app's CSP only
// allows 'self' scripts; works offline). public/webr/ is git-ignored and
// regenerated by predev/prebuild, so the ~45 MB never enters the repo.
import { cpSync, existsSync, mkdirSync, statSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const here = dirname(fileURLToPath(import.meta.url));
// The package exports map hides package.json; resolve the main entry
// (dist/webr.cjs) and use its folder.
const srcDir = dirname(require.resolve("webr"));
const outDir = join(here, "..", "public", "webr");

// Runtime files the webR worker fetches from its baseUrl. `vfs/` is the base
// R library (packages like stats, graphics, utils) mounted at start-up.
const ENTRIES = ["webr-worker.js", "R.js", "R.wasm", "libRblas.so", "libRlapack.so", "vfs"];

function size(p) {
  const st = statSync(p);
  if (!st.isDirectory()) return st.size;
  return readdirSync(p).reduce((a, f) => a + size(join(p, f)), 0);
}

mkdirSync(outDir, { recursive: true });
let bytes = 0;
let copied = 0;
for (const e of ENTRIES) {
  const src = join(srcDir, e);
  if (!existsSync(src)) continue;
  cpSync(src, join(outDir, e), { recursive: true });
  bytes += size(src);
  copied++;
}
// Production serves `require-trusted-types-for 'script'` (public/_headers),
// which also applies inside the webR worker: its importScripts() of R.js and
// Emscripten's eval would be blocked. Give the worker the same `default`
// policy the page installs (same-origin script URLs only; code strings pass
// through as the CSP already grants 'unsafe-eval').
const WORKER_TT_PRELUDE = `/* Lumen: Trusted Types default policy for the webR worker */
if (typeof self !== "undefined" && self.trustedTypes && !self.trustedTypes.defaultPolicy) {
  try {
    self.trustedTypes.createPolicy("default", {
      createScriptURL: function (u) {
        var url = new URL(u, self.location.href);
        if (url.origin !== self.location.origin) throw new TypeError("Blocked cross-origin script: " + u);
        return u;
      },
      createScript: function (s) { return s; },
    });
  } catch (e) { /* policy name not allowed: leave as is */ }
}
`;
const workerFile = join(outDir, "webr-worker.js");
if (existsSync(workerFile)) {
  const body = readFileSync(workerFile, "utf8");
  if (!body.startsWith("/* Lumen: Trusted Types")) writeFileSync(workerFile, WORKER_TT_PRELUDE + body);
}

console.log(`copy-webr: ${copied} entries → public/webr/ (${(bytes / 1e6).toFixed(1)} MB)`);
